// SPDX-License-Identifier: Apache-2.0
package com.m3.a3;

import com.m3.rewrite.atom.M3AtomizePureIntReturnRecipe;
import com.m3.rewrite.atom.M3PatternizePureIntAtomRecipe;
import java.io.IOException;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.net.URL;
import java.net.URLClassLoader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import javax.tools.ToolProvider;
import org.openrewrite.InMemoryExecutionContext;
import org.openrewrite.Parser;
import org.openrewrite.Recipe;
import org.openrewrite.SourceFile;
import org.openrewrite.internal.InMemoryLargeSourceSet;
import org.openrewrite.java.JavaParser;
import org.openrewrite.tree.ParseError;

/**
 * Compiler-driven A3 mastery lab for the retained Atomize/Patternize FILE recipes.
 *
 * <p>The lab generates bounded hostile Java fixtures in memory, executes every non-empty ordered
 * subset of the two retained source-changing atoms, recompiles after each recipe application,
 * compares public/protected contracts and runtime behavior, and requires equal-subset order
 * convergence plus a fixed point. It never writes JDK src/test trees.</p>
 */
public final class A3Lab {
    private static final int MAX_PASSES = 6;
    private static final List<List<String>> SCHEDULES =
            List.of(
                    List.of("A"),
                    List.of("P"),
                    List.of("A", "P"),
                    List.of("P", "A"),
                    List.of("A", "P", "A"),
                    List.of("P", "A", "P"));

    public record Result(
            int fixture,
            String schedule,
            String subset,
            String beforeSha,
            String afterSha,
            int applications,
            int compiles,
            boolean changed,
            boolean fixedPoint,
            boolean behaviorStable,
            boolean contractStable,
            boolean lexicalDataStable) {
        public Result {
            if (fixture < 0 || applications < 1 || compiles < 1) {
                throw new IllegalArgumentException("invalid A3Lab result");
            }
            schedule = text(schedule, "schedule");
            subset = text(subset, "subset");
            beforeSha = sha(beforeSha, "beforeSha");
            afterSha = sha(afterSha, "afterSha");
            if (!fixedPoint || !behaviorStable || !contractStable || !lexicalDataStable) {
                throw new IllegalArgumentException("A3Lab result did not pass");
            }
        }
    }

    private record Observation(
            List<String> contract,
            List<String> behavior,
            String payload) {}

    private record ResultAndSource(Result result, String source) {}

    private A3Lab() {}

    public static List<Result> run() throws Exception {
        ArrayList<Result> results = new ArrayList<>();
        int ordinal = 0;
        for (String fixture : A3Cases.fixtures()) {
            Observation baseline = verify(fixture, ordinal, "baseline", 0);
            A3Cases.Signal beforeSignal = A3Cases.signal(fixture);
            Map<String, String> normalForm = new LinkedHashMap<>();
            for (List<String> schedule : SCHEDULES) {
                ResultAndSource outcome =
                        converge(ordinal, fixture, schedule, baseline, beforeSignal);
                String prior = normalForm.putIfAbsent(outcome.result().subset(), outcome.source());
                if (prior != null && !prior.equals(outcome.source())) {
                    throw new IllegalStateException(
                            "A3Lab subset did not converge: " + outcome.result().subset());
                }
                results.add(outcome.result());
            }
            ordinal++;
        }
        return List.copyOf(results);
    }

    public static List<Result> write(Path root, Path out) throws Exception {
        Path checkedRoot = A3Fs.root(root);
        Path checkedOut = A3Fs.out(checkedRoot, out);
        List<Result> results = run();
        StringBuilder tsv =
                new StringBuilder(
                        "fixture\tschedule\tsubset\tbeforeSha\tafterSha\tapplications\tcompiles"
                                + "\tchanged\tfixedPoint\tbehaviorStable\tcontractStable"
                                + "\tlexicalDataStable\n");
        for (Result result : results) {
            tsv.append(result.fixture())
                    .append('\t')
                    .append(A3Fs.cell(result.schedule()))
                    .append('\t')
                    .append(A3Fs.cell(result.subset()))
                    .append('\t')
                    .append(result.beforeSha())
                    .append('\t')
                    .append(result.afterSha())
                    .append('\t')
                    .append(result.applications())
                    .append('\t')
                    .append(result.compiles())
                    .append('\t')
                    .append(result.changed())
                    .append('\t')
                    .append(result.fixedPoint())
                    .append('\t')
                    .append(result.behaviorStable())
                    .append('\t')
                    .append(result.contractStable())
                    .append('\t')
                    .append(result.lexicalDataStable())
                    .append('\n');
        }
        A3Fs.write(checkedRoot, checkedOut.resolve("results.tsv"), tsv.toString());
        return results;
    }

    public static int fixtureCount() {
        return A3Cases.fixtures().size();
    }

    public static int scheduleCount() {
        return SCHEDULES.size();
    }

    private static ResultAndSource converge(
            int fixtureOrdinal,
            String original,
            List<String> schedule,
            Observation baseline,
            A3Cases.Signal beforeSignal)
            throws Exception {
        String current = original;
        int compiles = 1;
        int applications = 0;
        boolean changed = false;
        boolean stable = false;

        for (int pass = 0; pass < MAX_PASSES; pass++) {
            String passStart = current;
            for (String atom : schedule) {
                current = apply(recipe(atom), current);
                applications++;
                Observation observed =
                        verify(
                                current,
                                fixtureOrdinal,
                                String.join("", schedule),
                                applications);
                compiles++;
                requireObservation(baseline, observed);
                A3Cases.requireStableData(beforeSignal, A3Cases.signal(current));
            }
            if (current.equals(passStart)) {
                stable = true;
                break;
            }
            changed = true;
        }
        if (!stable) {
            throw new IllegalStateException(
                    "A3Lab pass budget exhausted for " + String.join(">", schedule));
        }

        String replay = current;
        for (String atom : schedule) {
            replay = apply(recipe(atom), replay);
        }
        if (!current.equals(replay)) {
            throw new IllegalStateException(
                    "A3Lab second replay changed source for " + String.join(">", schedule));
        }

        Result result =
                new Result(
                        fixtureOrdinal,
                        String.join(">", schedule),
                        subset(schedule),
                        A3Fs.sha(original),
                        A3Fs.sha(current),
                        applications,
                        compiles,
                        changed,
                        true,
                        true,
                        true,
                        true);
        return new ResultAndSource(result, current);
    }

    private static Recipe recipe(String atom) {
        return switch (atom) {
            case "A" -> new M3AtomizePureIntReturnRecipe();
            case "P" -> new M3PatternizePureIntAtomRecipe();
            default -> throw new IllegalArgumentException("unknown A3Lab atom: " + atom);
        };
    }

    private static String apply(Recipe recipe, String source) {
        SourceFile parsed = parse(source);
        var context =
                new InMemoryExecutionContext(
                        error -> {
                            throw new IllegalStateException(error);
                        });
        var run =
                recipe.run(new InMemoryLargeSourceSet(List.of(parsed)), context, 4);
        var results = run.getChangeset().getAllResults();
        if (results.isEmpty()) {
            return source;
        }
        if (results.size() != 1 || results.getFirst().getAfter() == null) {
            throw new IllegalStateException("A3Lab recipe changed unexpected source set");
        }
        SourceFile after = Objects.requireNonNull(results.getFirst().getAfter(), "after");
        if (!after.getSourcePath().equals(parsed.getSourcePath())) {
            throw new IllegalStateException("A3Lab recipe changed source path");
        }
        String rendered = after.printAll();
        SourceFile reparsed = parse(rendered);
        if (!reparsed.printAll().equals(rendered)) {
            throw new IllegalStateException("A3Lab postimage did not round-trip");
        }
        return rendered;
    }

    private static SourceFile parse(String source) {
        var context =
                new InMemoryExecutionContext(
                        error -> {
                            throw new IllegalStateException(error);
                        });
        List<SourceFile> parsed =
                JavaParser.fromJavaVersion()
                        .build()
                        .parseInputs(
                                List.of(
                                        Parser.Input.fromString(
                                                Path.of("m3/lab/Subject.java"), source)),
                                null,
                                context)
                        .toList();
        if (parsed.size() != 1 || parsed.getFirst() instanceof ParseError) {
            throw new IllegalArgumentException("A3Lab could not parse generated Java 21");
        }
        if (!parsed.getFirst().printAll().equals(source)) {
            throw new IllegalArgumentException("A3Lab Java parse/print was not lossless");
        }
        return parsed.getFirst();
    }

    private static Observation verify(
            String source,
            int fixture,
            String schedule,
            int pass)
            throws Exception {
        Path dir = Files.createTempDirectory("a3lab-");
        try {
            Path java = dir.resolve("m3/lab/Subject.java");
            Files.createDirectories(java.getParent());
            Files.writeString(java, source, StandardCharsets.UTF_8);
            int compiled =
                    ToolProvider.getSystemJavaCompiler()
                            .run(
                                    null,
                                    null,
                                    null,
                                    "--release",
                                    "21",
                                    "-Xlint:all",
                                    "-Werror",
                                    "-d",
                                    dir.toString(),
                                    java.toString());
            if (compiled != 0) {
                throw new IllegalStateException(
                        "A3Lab javac gate failed fixture="
                                + fixture
                                + " schedule="
                                + schedule
                                + " pass="
                                + pass);
            }

            try (URLClassLoader loader =
                    new URLClassLoader(new URL[] {dir.toUri().toURL()}, null)) {
                Class<?> type = loader.loadClass("m3.lab.Subject");
                List<String> contract = contract(type);
                Method probe = type.getMethod("probe", int.class, int.class);
                Method matches = type.getMethod("matches", String.class);
                Method payload = type.getMethod("payload");

                ArrayList<String> behavior = new ArrayList<>();
                for (int[] pair :
                        List.of(
                                new int[] {0, 0},
                                new int[] {1, 2},
                                new int[] {-7, 3},
                                new int[] {Integer.MAX_VALUE, 1})) {
                    behavior.add(
                            pair[0]
                                    + ","
                                    + pair[1]
                                    + "="
                                    + probe.invoke(null, pair[0], pair[1]));
                }
                for (String value :
                        List.of(
                                "return (a+b)*31;",
                                "if (x) { return y; }",
                                "plain text",
                                "a+b?")) {
                    behavior.add("m:" + value + "=" + matches.invoke(null, value));
                }
                return new Observation(
                        contract,
                        List.copyOf(behavior),
                        Objects.toString(payload.invoke(null), ""));
            }
        } finally {
            deleteTree(dir);
        }
    }

    private static List<String> contract(Class<?> type) {
        ArrayList<String> rows = new ArrayList<>();
        for (Method method : type.getDeclaredMethods()) {
            int modifiers = method.getModifiers();
            if (Modifier.isPublic(modifiers) || Modifier.isProtected(modifiers)) {
                rows.add(
                        "M:"
                                + Modifier.toString(modifiers)
                                + ":"
                                + method.getName()
                                + ":"
                                + method.getReturnType().getTypeName()
                                + ":"
                                + List.of(method.getParameterTypes()).stream()
                                        .map(Class::getTypeName)
                                        .toList());
            }
        }
        for (Field field : type.getDeclaredFields()) {
            int modifiers = field.getModifiers();
            if (Modifier.isPublic(modifiers) || Modifier.isProtected(modifiers)) {
                rows.add(
                        "F:"
                                + Modifier.toString(modifiers)
                                + ":"
                                + field.getName()
                                + ":"
                                + field.getType().getTypeName());
            }
        }
        rows.sort(Comparator.naturalOrder());
        return List.copyOf(rows);
    }

    private static void requireObservation(Observation expected, Observation actual) {
        if (!expected.contract().equals(actual.contract())) {
            throw new IllegalStateException("A3Lab public/protected contract drift");
        }
        if (!expected.behavior().equals(actual.behavior())) {
            throw new IllegalStateException("A3Lab behavior drift");
        }
        if (!expected.payload().equals(actual.payload())) {
            throw new IllegalStateException("A3Lab code-looking data drift");
        }
    }

    private static String subset(List<String> schedule) {
        return schedule.stream()
                .distinct()
                .sorted()
                .reduce((left, right) -> left + "+" + right)
                .orElseThrow();
    }

    private static String text(String value, String field) {
        String checked = Objects.toString(value, "").strip();
        if (checked.isEmpty()
                || checked.indexOf('\0') >= 0
                || checked.indexOf('\n') >= 0
                || checked.indexOf('\r') >= 0
                || checked.indexOf('\t') >= 0) {
            throw new IllegalArgumentException(field);
        }
        return checked;
    }

    private static String sha(String value, String field) {
        String checked = text(value, field);
        if (!checked.matches("[0-9a-f]{64}")) {
            throw new IllegalArgumentException(field);
        }
        return checked;
    }

    private static void deleteTree(Path root) {
        if (root == null || !Files.exists(root)) {
            return;
        }
        try (var stream = Files.walk(root)) {
            stream.sorted(Comparator.reverseOrder())
                    .forEach(
                            path -> {
                                try {
                                    Files.deleteIfExists(path);
                                } catch (IOException ignored) {
                                    // Temporary compiler output cleanup is best effort.
                                }
                            });
        } catch (IOException ignored) {
            // Temporary compiler output cleanup is best effort.
        }
    }
}
